package com.orderflow.notification.messaging;import tools.jackson.databind.ObjectMapper;import com.orderflow.events.NotificationDispatchRequestedEvent;import com.orderflow.notification.service.NotificationDispatchService;import org.springframework.kafka.annotation.KafkaListener;import org.springframework.messaging.handler.annotation.Header;import org.springframework.stereotype.Component;@Component public class DispatchEventListener{private final ObjectMapper m;private final NotificationDispatchService s;public DispatchEventListener(ObjectMapper m,NotificationDispatchService s){this.m=m;this.s=s;}@KafkaListener(topics="${app.kafka.topics.notification-events}",groupId="notification-service-dispatch-v1")public void consume(String payload,@Header("eventType")String type)throws Exception{if(!"NOTIFICATION_DISPATCH_REQUESTED".equals(type))return;s.dispatch(m.readValue(payload,NotificationDispatchRequestedEvent.class));}}
